def stats(x):
    eq=peak=closed_peak=100.;dd=closed_dd=0.
    for r in x.itertuples():
        risk=eq*.005;peak=max(peak,eq+risk*r.max_r);dd=max(dd,100*(peak-eq-risk*r.min_r)/peak);eq+=risk*r.net_r;peak=max(peak,eq);closed_peak=max(closed_peak,eq);closed_dd=max(closed_dd,100*(closed_peak-eq)/closed_peak)
    pos=x.loc[x.net_r>0,'net_r'].sum();neg=-x.loc[x.net_r<0,'net_r'].sum()
    return dict(trades=len(x),pf_net_r=float(pos/neg) if neg else None,sum_r=float(x.net_r.sum()),win_pct=float(100*(x.net_r>0).mean()),balance_100=eq,drawdown_model_bound_pct=dd,closed_drawdown_pct=closed_dd)

