def candles(ax,z,minutes):
    dates=md.date2num(z.index.tz_convert('Asia/Jakarta').tz_localize(None));width=minutes/1440*.7
    for x,r in zip(dates,z.itertuples()):
        color='#149f81' if r.close>=r.open else '#cf5864';ax.vlines(x,r.low,r.high,color=color,lw=.9);ax.add_patch(Rectangle((x-width/2,min(r.open,r.close)),width,max(abs(r.close-r.open),.03),fc=color,ec=color))
    ax.xaxis.set_major_locator(md.HourLocator(interval=6) if minutes==60 else md.MinuteLocator(byminute=[0,15,30,45]))
    ax.xaxis.set_major_formatter(md.DateFormatter('%d/%m %H:%M'));ax.grid(alpha=.15);ax.set_ylabel('XAUUSD · USD/ons')
for ax,z,minutes in [(axes[0],h.loc[entry-pd.Timedelta(hours=32):exit+pd.Timedelta(hours=5)],60),(axes[1],m5.loc[touch-pd.Timedelta(hours=1):entry+pd.Timedelta(hours=1)],5)]:
    candles(ax,z,minutes)
    if zone:ax.axhspan(*zone,color='#e9bd52',alpha=.22,label='FVG H1 tersedia sebelum entry')
    ax.axhline(level,color='#b58b24',ls='--',label='50% FVG H1')
    x=md.date2num(entry.tz_convert('Asia/Jakarta').tz_localize(None));ax.axvline(x,color='#173f70',ls=':',label='Entry setelah M5 reclaim')
    ax.scatter([x],[example.entry],marker='^' if side==1 else 'v',color='#173f70',s=65,zorder=5)
outcome={1:'SL',2:'TP penuh',3:'batas waktu',4:'trailing stop'}[int(example.reason)]
